SELECT * FROM a NATURAL FULL JOIN b ORDER BY 1, 2, 3, 4, 5, 6;
SELECT g, t FROM a WHERE id > 4 UNION SELECT aid, t FROM b ORDER BY 1, 2;
SELECT coalesce(a.id, 1), (b.w * -1) FROM a FULL JOIN b ON b.aid = a.g WHERE a.g IS NOT 0 ORDER BY 1, 2;
WITH RECURSIVE c(x) AS (SELECT 2 UNION ALL SELECT x + 2 FROM c WHERE x < 3) SELECT x, (SELECT count(*) FROM a WHERE a.g <= c.x) FROM c ORDER BY 1, 2;
SELECT id, json_set(doc, '$', NULL), json_remove(doc, '$') FROM j ORDER BY 1, 2, 3;
SELECT j.id, t.fullkey, t.type, t.atom FROM j, json_tree(j.doc) t ORDER BY 1, 2, 3, 4;
